class TestACEEConfig:
    """Test ACEE configuration validation and defaults."""

    def test_default_config_creation(self):
        """Test that default config has sensible values."""
        config = ACEEConfig()
        assert config.max_code_length > 0
        assert config.execution_timeout > 0
        assert config.max_memory_mb > 0
        assert config.safety_level in ["strict", "moderate", "permissive"]
        assert isinstance(config.blocked_patterns, list)

    def test_config_validation(self):
        """Test configuration validation raises appropriate errors."""
        with pytest.raises(ValueError, match="max_code_length must be positive"):
            ACEEConfig(max_code_length=-1)
        
        with pytest.raises(ValueError, match="execution_timeout must be positive"):
            ACEEConfig(execution_timeout=0)
        
        with pytest.raises(ValueError, match="Invalid safety_level"):
            ACEEConfig(safety_level="invalid")

    def test_config_serialization(self):
        """Test config serialization to/from dict."""
        config = ACEEConfig(
            max_code_length=5000,
            execution_timeout=60,
            safety_level="moderate"
        )
        config_dict = config.to_dict()
        restored_config = ACEEConfig.from_dict(config_dict)
        assert restored_config.max_code_length == config.max_code_length
        assert restored_config.execution_timeout == config.execution_timeout
        assert restored_config.safety_level == config.safety_level


