    @pytest.mark.asyncio
    async def test_error_recovery_flow(
        self,
        acee_unit: ACEEUnit,
        mock_llm_client: MagicMock
    ):
        """Test error recovery and retry logic."""
        # Simulate transient failure then success
        call_count = 0
        
        async def flaky_generation(*args, **kwargs):
            nonlocal call_count
            call_count += 1
            if call_count == 1:
                raise Exception("Transient error")
            return {"text": "def retry_func(): return 'success'"}
        
        mock_llm_client.generate.side_effect = flaky_generation
        
        response = await acee_unit.generate_code_with_retry(
            CodeGenerationRequest(prompt="test", language="python"),
            max_retries=3
        )
        
        assert response.success is True
        assert call_count == 2  # First failed, second succeeded

    @pytest.mark.asyncio
    async def test_concurrent_execution_limits(
        self,
        acee_unit: ACEEUnit
    ):
        """Test concurrent execution limits are enforced."""
        requests = [
            CodeGenerationRequest(prompt=f"test_{i}", language="python")
            for i in range(20)  # More than max_concurrent_executions
        ]
        
        tasks = [acee_unit.generate_code(req) for req in requests]
        
        with pytest.raises(ResourceLimitError, match="Too many concurrent executions"):
            await asyncio.gather(*tasks)


