class TestPerformance:
    """Test performance characteristics."""

    @pytest.mark.asyncio
    async def test_generation_latency(
        self,
        acee_unit: ACEEUnit,
        benchmark
    ):
        """Test code generation latency meets SLA."""
        async def generate():
            return await acee_unit.generate_code(
                CodeGenerationRequest(prompt="simple function", language="python")
            )
        
        result = await benchmark(generate)
        assert result.success is True

    @pytest.mark.asyncio
    async def test_batch_processing(
        self,
        acee_unit: ACEEUnit
    ):
        """Test batch processing performance."""
        requests = [
            CodeGenerationRequest(prompt=f"func_{i}", language="python")
            for i in range(10)
        ]
        
        start_time = datetime.now()
        results = await asyncio.gather(*[
            acee_unit.generate_code(req) for req in requests
        ])
        total_time = (datetime.now() - start_time).total_seconds()
        
        assert all(r.success for r in results)
        assert total_time < 5.0  # Should complete within 5 seconds

    @pytest.mark.asyncio
    async def test_memory_usage(
        self,
        acee_unit: ACEEUnit
    ):
        """Test memory usage stays within limits."""
        import tracemalloc
        tracemalloc.start()
        
        await acee_unit.generate_code(
            CodeGenerationRequest(prompt="memory test", language="python")
        )
        
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        
        assert peak < acee_unit.config.max_memory_mb * 1024 * 1024


