class TestSecurity:
    """Test security boundaries and attack vectors."""

    @pytest.mark.asyncio
    async def test_injection_attacks(
        self,
        acee_unit: ACEEUnit
    ):
        """Test protection against injection attacks."""
        injection_prompts = [
            "'; DROP TABLE users; --",
            "${system('rm -rf /')}",
            "{{config}}",
            "<script>alert('xss')</script>",
            "__import__('os').system('ls')"
        ]
        
        for prompt in injection_prompts:
            with pytest.raises((SafetyViolationError, ValueError)):
                await acee_unit.generate_code(
                    CodeGenerationRequest(prompt=prompt, language="python")
                )

    @pytest.mark.asyncio
    async def test_resource_exhaustion(
        self,
        acee_unit: ACEEUnit
    ):
        """Test protection against resource exhaustion."""
        # Attempt to create infinite loop
        infinite_loop = "while True: pass"
        
        with pytest.raises((ExecutionTimeoutError, ResourceLimitError)):
            await acee_unit.execute_code(infinite_loop, timeout=1)

    @pytest.mark.asyncio
    async def test_privilege_escalation(
        self,
        acee_unit: ACEEUnit
    ):
        """Test protection against privilege escalation attempts."""
        escalation_attempts = [
            "import ctypes; ctypes.CDLL(None)",
            "import sys; sys.modules['os'] = None",
            "__builtins__['__import__']('subprocess')",
            "().__class__.__bases__[0].__subclasses__()"
        ]
        
        for attempt in escalation_attempts:
            with pytest.raises(SafetyViolationError):
                await acee_unit.validate_safety(attempt)


