class TestStateManagement:
    """Test ACEE state management and persistence."""

    @pytest.mark.asyncio
    async def test_state_persistence(
        self,
        acee_unit: ACEEUnit
    ):
        """Test state persistence across operations."""
        # Generate code and save state
        response1 = await acee_unit.generate_code(
            CodeGenerationRequest(prompt="function a", language="python")
        )
        
        # Save state
        state = acee_unit.get_state()
        
        # Create new unit and restore state
        new_unit = ACEEUnit(
            config=acee_unit.config,
            llm_client=acee_unit.llm_client,
            safety_validator=acee_unit.safety_validator,
            execution_sandbox=acee_unit.execution_sandbox
        )
        new_unit.restore_state(state)
        
        # Verify state was restored
        assert new_unit.generation_count == acee_unit.generation_count
        assert new_unit.total_execution_time == acee_unit.total_execution_time

    @pytest.mark.asyncio
    async def test_concurrent_state_isolation(
        self,
        acee_unit: ACEEUnit
    ):
        """Test state isolation between concurrent operations."""
        async def generate_and_track(request_id: int):
            response = await acee_unit.generate_code(
                CodeGenerationRequest(
                    prompt=f"func_{request_id}",
                    language="python"
                )
            )
            return response
        
        # Run concurrent operations
        tasks = [generate_and_track(i) for i in range(5)]
        results = await asyncio.gather(*tasks)
        
        # Verify all operations completed successfully
        assert all(r.success for r in results)
        assert len(set(r.code for r in results)) == 5  # All unique


