class TestCleanup:
    """Test resource cleanup and teardown."""

    @pytest.mark.asyncio
    async def test_resource_cleanup(
        self,
        acee_unit: ACEEUnit
    ):
        """Test proper cleanup of resources."""
        # Create temporary files
        with tempfile.NamedTemporaryFile(suffix='.py', delete=False) as f:
            f.write(b"print('test')")
            temp_path = f.name
        
        try:
            # Execute code that uses temp file
            await acee_unit.execute_code(
                f"import os; os.unlink('{temp_path}')"
            )
        finally:
            # Verify cleanup
            assert not os.path.exists(temp_path)

    @pytest.mark.asyncio
    async def test_connection_pool_cleanup(
        self,
        acee_unit: ACEEUnit
    ):
        """Test cleanup of connection pools."""
        # Perform multiple operations
        for _ in range(10):
            await acee_unit.generate_code(
                CodeGenerationRequest(prompt="test", language="python")
            )
        
        # Trigger cleanup
        await acee_unit.cleanup()
        
        # Verify connections are closed
        assert acee_unit.llm_client.is_closed is True


